def test_source_ranked_candidate_identity_and_checkpoint_round_trip() -> None:
    candidate = replace(
        _source_test_candidate(
            target="a white dwarf",
            level_range=(15, 19),
            specials=("spec_cast_mage",),
            autonomy_rejections=(
                "target has special procedure spec_cast_mage",
            ),
        ),
        combat_readiness="direct=magic missile; defense=armor",
        combat_readiness_bonus=7,
        route_preflight_room_vnum="1300",
        route_preflight_command="where shadow guardian",
        route_preflight_target="shadow guardian",
        route_preflight_level_range=(7, 11),
        route_preflight_hard_hazard=False,
        route_hard_hazard_targets=("Fewmaster Toede",),
        requires_flight=True,
    )
    record = _source_ranked_candidate_record(
        candidate,
        character_level=19,
    )
    restored = _source_ranked_candidate_from_record(record)

    assert _source_ranked_target_identity(candidate) == "white dwarf"
    assert _source_ranked_policy_id(candidate, character_level=19).startswith(
        "source-ranked-hunt-test-100-200-19"
    )
    assert restored == candidate
    assert record["requires_flight"] is True
    assert record["combat_readiness"] == candidate.combat_readiness
    assert record["combat_readiness_bonus"] == 7


