def test_source_ranked_area_circuit_keeps_only_safe_linked_targets() -> None:
    rooms = {
        200: RoomSource(
            200,
            "Primary Room",
            "test.are",
            exits={"east": ExitSource("east", 201, 0, -1)},
        ),
        201: RoomSource(
            201,
            "Secondary Room",
            "test.are",
            exits={
                "west": ExitSource("west", 200, 0, -1),
                "east": ExitSource("east", 202, 0, -1),
            },
        ),
        202: RoomSource(
            202,
            "Hazard Room",
            "test.are",
            exits={
                "west": ExitSource("west", 201, 0, -1),
                "east": ExitSource("east", 203, 0, -1),
            },
        ),
        203: RoomSource(
            203,
            "Blocked Target Room",
            "test.are",
            exits={"west": ExitSource("west", 202, 0, -1)},
        ),
    }
    world = WorldSource(
        mobiles={
            100: MobileSource(
                100, "primary", "the primary target", 19,
                ACT_SENTINEL, 0, "test.are",
            ),
            101: MobileSource(
                101, "secondary", "the secondary target", 19,
                ACT_SENTINEL, 0, "test.are",
            ),
            102: MobileSource(
                102, "blocked", "the blocked target", 19,
                ACT_SENTINEL, 0, "test.are",
            ),
            999: MobileSource(
                999, "hazard", "a dangerous caster", 19,
                ACT_SENTINEL, 0, "test.are",
            ),
        },
        rooms=rooms,
        mob_resets=[
            MobReset(100, 200, 1, ()),
            MobReset(101, 201, 1, ()),
            MobReset(102, 203, 1, ()),
            MobReset(999, 202, 1, ()),
        ],
        mobile_specials={999: ("spec_cast_mage",)},
    )
    primary = _source_test_candidate(
        target="the primary target",
        level_range=(17, 21),
        mobile_vnum=100,
        room_vnum=200,
    )
    secondary = _source_test_candidate(
        target="the secondary target",
        level_range=(17, 21),
        mobile_vnum=101,
        room_vnum=201,
    )
    blocked = _source_test_candidate(
        target="the blocked target",
        level_range=(17, 21),
        mobile_vnum=102,
        room_vnum=203,
    )

    extras = _source_ranked_area_circuit_candidates(
        primary,
        (primary, secondary, blocked),
        world,
        {"level": 19, "max_hp": 200, "world_boot_id": "boot-1"},
        character_level=19,
    )
    stops = _source_ranked_circuit_hunt_stops(
        primary,
        extras,
        world,
        character_level=19,
    )

    assert extras == (secondary,)
    assert [stop.source_mobile_vnum for stop in stops] == [100, 101]
    assert stops[1].route_vnums == ("201",)
    assert stops[0].minimum_health_ratio == 0.85
    assert stops[1].minimum_health_ratio == 0.225

    protected_state = {
        "level": 19,
        "world_boot_id": "boot-1",
        "combat_pouch_potions": {"purple": 1},
        "campaign_source_ranked_xp_loss_policies": [{
            "boot_id": "boot-1",
            "level": 19,
            "policy_id": _source_ranked_policy_id(
                primary,
                character_level=19,
            ),
            "xp_delta": -218,
        }],
    }
    protected_stops = _source_ranked_circuit_hunt_stops(
        primary,
        (),
        world,
        character_level=19,
        state=protected_state,
    )
    assert protected_stops[0].require_sanctuary is True

    high_risk_stops = _source_ranked_circuit_hunt_stops(
        primary,
        (replace(secondary, specials=("spec_fido",)),),
        world,
        character_level=19,
    )

    assert high_risk_stops[1].minimum_health_ratio == 0.675

    capped_primary = replace(primary, boot_kills=4)
    capped_secondary = replace(secondary, boot_kills=4)
    capped_candidates = (capped_primary, capped_secondary, blocked)
    assert _source_ranked_area_circuit_candidates(
        capped_primary,
        capped_candidates,
        world,
        {"level": 19, "max_hp": 200, "world_boot_id": "boot-1"},
        character_level=19,
    ) == ()
    repeatable_policy_ids = {
        _source_ranked_policy_id(candidate, character_level=19)
        for candidate in (capped_primary, capped_secondary)
    }
    assert _source_ranked_area_circuit_candidates(
        capped_primary,
        capped_candidates,
        world,
        {"level": 19, "max_hp": 200, "world_boot_id": "boot-1"},
        character_level=19,
        allow_repeated_policy_ids=repeatable_policy_ids,
    ) == (capped_secondary,)


