def test_throughput_repair_requires_one_fresh_training_audit() -> None:
    marker = {
        "level": 19,
        "policy_id": "source-ranked-hunt-test-100-200-19",
        "limits": ["mana"],
    }
    state = {_SOURCE_RANKED_THROUGHPUT_LIMIT_KEY: marker}

    assert _source_ranked_training_reaudit_required(
        state,
        character_level=19,
    )

    repaired = _with_source_ranked_throughput_reaudit(
        state,
        state,
        character_level=19,
        run_id=77,
        training_complete=True,
        gear_audit_complete=True,
    )

    assert not _source_ranked_training_reaudit_required(
        repaired,
        character_level=19,
    )
    assert repaired[_SOURCE_RANKED_THROUGHPUT_LIMIT_KEY][
        "training_reaudit_run_id"
    ] == 77
    assert repaired[_SOURCE_RANKED_THROUGHPUT_LIMIT_KEY][
        "gear_audit_completed"
    ] is True


def test_training_policy_revision_reopens_stale_trainer_audit() -> None:
    key = "campaign_training_policy_revision"

    assert _training_policy_revision_stale({})
    assert _training_policy_revision_stale(
        {key: _CAMPAIGN_POLICY_REVISION - 1}
    )
    assert not _training_policy_revision_stale(
        {key: _CAMPAIGN_POLICY_REVISION}
    )

    refreshed = _refresh_policy_revision(
        {"campaign_policy_revision": _CAMPAIGN_POLICY_REVISION - 1}
    )
    assert refreshed[key] == _CAMPAIGN_POLICY_REVISION - 1


def test_policy_revision_reopens_retryable_fame_routes_for_protected_bound() -> None:
    circus_id = _FAME_RECOVERY_CIRCUS_POLICY.policy_id
    mirror_id = _FAME_RECOVERY_POLICY.policy_id
    state = {
            # Revision 185 introduced the fame-bound repair; later revisions
            # add targeted Mirror Guardian revalidations below.
            "campaign_policy_revision": 184,
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            circus_id: {
                "boot_id": "boot-1",
                "completed_kill": False,
                "retryable_failure": True,
                "viable": False,
            },
            mirror_id: {
                "boot_id": "boot-1",
                "completed_kill": False,
                "retryable_failure": True,
                "viable": False,
            },
            _FAME_RECOVERY_LOTUS_POLICY.policy_id: {
                "boot_id": "boot-1",
                "completed_kill": False,
                "fatal_failure": True,
                "viable": False,
            },
        },
        "campaign_research_absence_cooldowns": {
            circus_id: 3,
            mirror_id: 3,
        },
    }

    refreshed = _refresh_policy_revision(state)

    assert refreshed["campaign_policy_revision"] == _CAMPAIGN_POLICY_REVISION
    assert "campaign_research_absence_cooldowns" not in refreshed
    for policy_id in (circus_id, mirror_id):
        result = refreshed["campaign_research_results"][policy_id]
        assert result["retryable_failure"] is True
        assert result["superseded_by_policy_revision"] == 185
    assert (
        refreshed["campaign_research_results"][_FAME_RECOVERY_LOTUS_POLICY.policy_id]
        ["fatal_failure"]
        is True
    )


