def test_source_ranked_wanderer_uses_locator_and_source_reachable_rooms() -> None:
    world = WorldSource(
        mobiles={
            100: MobileSource(
                100,
                "wanderer",
                "a wandering target",
                5,
                1 << 6,
                0,
                "test.are",
            )
        },
        rooms={
            200: RoomSource(
                200,
                "Origin Room",
                "test.are",
                exits={
                    "east": ExitSource("east", 201, 0, -1),
                },
            ),
            201: RoomSource(
                201,
                "Middle Room",
                "test.are",
                exits={
                    "west": ExitSource("west", 200, 0, -1),
                    "east": ExitSource("east", 202, 0, -1),
                },
            ),
            202: RoomSource(
                202,
                "Far Room",
                "test.are",
                exits={
                    "west": ExitSource("west", 201, 0, -1),
                },
            ),
        },
        mob_resets=[MobReset(100, 200, 1, ())],
    )
    candidate = replace(
        _source_test_candidate(
            target="a wandering target",
            level_range=(3, 5),
            mobile_vnum=100,
            room_vnum=200,
        ),
        target_keyword="wanderer",
        sentinel=False,
        stay_area=True,
    )

    stops = _source_ranked_hunt_stops(candidate, world)

    assert stops[0].target is None
    assert stops[0].actions == ("where wanderer",)
    assert stops[0].abort_if_where_target_absent is True
    assert dict(stops[0].where_location_routes)["far room"] == ("202",)
    assert [stop.route_vnums for stop in stops[1:]] == [
        ("200",),
        ("201",),
        ("202",),
    ]
    assert [stop.crowd_retry_limit for stop in stops[1:]] == [8, 4, 8]
    assert all(
        stop.crowd_retry_delay_seconds == 12.0
        for stop in stops[1:]
    )

    assert stops[0].abort_if_where_location_unknown is True
    assert stops[0].preserve_where_route_waypoints is True
    assert {
        origin for origin, _label, _route in stops[0].where_relocation_routes
    } == {"200", "201", "202"}


def test_source_ranked_stops_skip_water_reset_without_capability() -> None:
    world = WorldSource(
        mobiles={
            100: MobileSource(
                100,
                "sentinel",
                "a water sentinel",
                15,
                ACT_SENTINEL,
                0,
                "test.are",
            )
        },
        rooms={
            200: RoomSource(
                200,
                "Land Room",
                "test.are",
                exits={"east": ExitSource("east", 202, 0, -1)},
            ),
            202: RoomSource(
                202,
                "Water Room",
                "test.are",
                exits={"west": ExitSource("west", 200, 0, -1)},
                sector_type=6,
            ),
        },
        mob_resets=[
            MobReset(100, 200, 1, ()),
            MobReset(100, 202, 1, ()),
        ],
    )
    candidate = replace(
        _source_test_candidate(
            target="a water sentinel",
            level_range=(13, 17),
            mobile_vnum=100,
            room_vnum=200,
        ),
        target_keyword="sentinel",
    )

    land_only = _source_ranked_hunt_stops(
        candidate,
        world,
        character_level=17,
        state={"affects": [], "inventory": [], "race": "dwarf"},
    )
    with_flight = _source_ranked_hunt_stops(
        candidate,
        world,
        character_level=17,
        state={"affects": [[{"name": "fly"}]], "inventory": []},
    )

    assert [stop.route_vnums for stop in land_only] == [("200",)]
    assert [stop.route_vnums for stop in with_flight] == [
        ("200",),
        ("202",),
    ]
    assert _source_ranked_movement_capability_available(
        {"race": "sahuagin", "affects": [], "inventory": []}
    )


