def test_source_ranked_reset_retry_reopens_absence_but_not_route_hazard() -> None:
    absent_candidate = _source_test_candidate(
        target="a white dwarf",
        level_range=(15, 19),
    )
    absent_policy_id = _source_ranked_policy_id(
        absent_candidate,
        character_level=19,
    )
    absent_state = {
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            absent_policy_id: {
                "boot_id": "boot-1",
                "observed": False,
                "absent": True,
                "viable": False,
            }
        },
        "campaign_research_absence_cooldowns": {absent_policy_id: 3},
    }

    assert (
        _source_ranked_result_status(
            absent_candidate,
            absent_state,
            character_level=19,
        )
        == "cooldown"
    )
    assert (
        _source_ranked_result_status(
            absent_candidate,
            absent_state,
            character_level=19,
            allow_cooldown_retry=True,
        )
        == "retryable"
    )

    hazard_state = {
        "world_boot_id": "boot-1",
        "campaign_research_results": {
            absent_policy_id: {
                "boot_id": "boot-1",
                "observed": False,
                "route_hazard": "source hazard",
                "viable": False,
            }
        },
        "campaign_research_absence_cooldowns": {absent_policy_id: 3},
    }
    assert (
        _source_ranked_result_status(
            absent_candidate,
            hazard_state,
            character_level=19,
            allow_cooldown_retry=True,
        )
        == "cooldown"
    )


