def test_source_ranked_runner_does_not_open_all_cooldowns_for_retry_marker(
    tmp_path,
    monkeypatch,
) -> None:
    config_path, _ = _write_campaign_files(tmp_path)
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)
    candidate = _source_test_candidate(
        target="a fresh target",
        level_range=(17, 19),
    )
    captured: list[bool] = []
    ranked_kwargs: dict[str, object] = {}

    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: WorldSource(),
    )
    def capture_rank(*args, **kwargs):
        ranked_kwargs.update(kwargs)
        return (candidate,)

    monkeypatch.setattr("dd4tester.campaign.rank_hunt_candidates", capture_rank)
    monkeypatch.setattr(
        "dd4tester.campaign._shortest_paths_from",
        lambda *args, **kwargs: {},
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_route_live_navigation",
        lambda *args, **kwargs: None,
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_route_has_static_safe_live_navigation_path",
        lambda *args, **kwargs: True,
    )

    def capture_selection(*args, **kwargs):
        captured.append(bool(kwargs["allow_cooldown_retry"]))
        return None

    monkeypatch.setattr(
        "dd4tester.campaign._select_source_ranked_hunt_candidate",
        capture_selection,
    )
    runner._select_source_ranked_candidate(
        {
            "level": 19,
            "max_hp": 264,
            "world_boot_id": "boot-1",
            "affects": [[{"name": "fly"}]],
            "campaign_known_skills": ["magic missile"],
            _SOURCE_RANKED_RETRY_EXHAUSTED_KEY: (
                "source-ranked-hunt-old-target-1-2-19"
            ),
        }
    )

    assert captured == [False]
    assert ranked_kwargs["character_class"] == "mage"
    assert ranked_kwargs["character_subclass"] is None
    assert ranked_kwargs["known_skills"] == ("magic missile",)


def test_source_ranked_runner_deduplicates_recall_origin_path_searches(
    tmp_path,
    monkeypatch,
) -> None:
    config_path, _database = _write_campaign_files(tmp_path)
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)
    first = _source_test_candidate(
        target="the first origin target",
        level_range=(17, 19),
        mobile_vnum=100,
        room_vnum=200,
    )
    second = replace(
        first,
        target="the second origin target",
        target_keyword="target",
        mobile_vnum=101,
        room_vnum=201,
    )
    path_origins: list[int] = []

    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: WorldSource(),
    )
    monkeypatch.setattr(
        "dd4tester.campaign.rank_hunt_candidates",
        lambda *args, **kwargs: (first, second),
    )

    def record_path_search(rooms, origin, **kwargs):
        path_origins.append(origin)
        return {
            200: (("south",), (3001, 200), 0),
            201: (("south",), (3001, 201), 0),
        }

    monkeypatch.setattr(
        "dd4tester.campaign._shortest_paths_from",
        record_path_search,
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_route_live_navigation",
        lambda *args, **kwargs: {},
    )
    monkeypatch.setattr(
        "dd4tester.campaign._source_ranked_route_has_static_safe_live_navigation_path",
        lambda *args, **kwargs: True,
    )

    selected = runner._select_source_ranked_candidate(
        {
            "level": 19,
            "max_hp": 264,
            "world_boot_id": "boot-1",
            "affects": [],
        }
    )

    assert selected == first
    assert path_origins == [3001]


