def test_legacy_completed_liquidation_checkpoint_gains_a_baseline(tmp_path) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    with RunStorage(database) as storage:
        campaign_id = storage.create_campaign(
            name=spec.name,
            config_path=config_path.resolve(),
            character_profile_path=spec.character_profile,
            target_level=spec.target_level,
        )
        storage.record_campaign_checkpoint(
            campaign_id,
            segment_id=None,
            run_id=None,
            phase="liquidate-loot",
            reason="segment_complete",
            state={
                "level": 7,
                "xp": 21_058,
                "inventory": [[
                    {"short_desc": "a metal shield"},
                    {"short_desc": "a big pot pie"},
                ]],
            },
        )

        runner = CampaignRunner(spec, config_path)
        resumed_id, state = runner._open_campaign(storage)

    assert resumed_id == campaign_id
    assert state["campaign_liquidation_baseline"] == ["metal shield"]
    assert runner._policy_for_state(state).policy_id != "liquidate-loot"


def test_noop_liquidation_does_not_baseline_unchanged_inventory(tmp_path) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    policy = ProgressionPolicy(
        policy_id="liquidate-loot",
        minimum_level=2,
        maximum_level=None,
        status="verified",
        execution="sell-loot",
        summary="Sell expendable equipment.",
        evidence=(),
        practice_skill=None,
    )
    initial_state = {
        "name": "Campaignmage",
        "level": 8,
        "xp": 20_000,
        "room_vnum": "3054",
        "area": "Midgaard",
        "inventory": [[{"short_desc": "hard leather boots"}]],
        "campaign_worn_equipment": [],
    }
    with RunStorage(database) as storage:
        campaign_id = storage.create_campaign(
            name=spec.name,
            config_path=config_path.resolve(),
            character_profile_path=spec.character_profile,
            target_level=spec.target_level,
        )
        storage.record_campaign_checkpoint(
            campaign_id,
            segment_id=None,
            run_id=None,
            phase="ready",
            reason="ready",
            state=initial_state,
        )

    async def noop_segment(character, profile_path: Path) -> RunResult:
        return _record_segment_run(
            database,
            profile_path,
            dict(initial_state),
            scenario_name="sell-loot:Campaignmage",
        )

    class LiquidationRunner(CampaignRunner):
        def _policy_for_state(self, state) -> ProgressionPolicy:
            return policy

    result = asyncio.run(
        LiquidationRunner(
            spec,
            config_path,
            segment_runner=noop_segment,
        ).run()
    )

    assert result.status == "ready"
    assert "campaign_liquidation_baseline" not in result.state


def test_blocked_liquidation_failure_preserves_live_hazard_and_resumes(
    tmp_path,
) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    policy = ProgressionPolicy(
        policy_id="liquidate-loot",
        minimum_level=2,
        maximum_level=None,
        status="verified",
        execution="sell-loot",
        summary="Sell expendable equipment.",
        evidence=(),
        practice_skill=None,
    )
    state = {
        "name": "Campaignmage",
        "level": 25,
        "xp": 377_925,
        "room_vnum": "3054",
        "area": "Midgaard",
        "room_flags": ["safe", "healing"],
        "inventory": [[{"short_desc": "a long slim dagger"}]],
        "campaign_worn_equipment": ["a Goblin Sentry's Sword"],
        "character_class": "Warrior",
        "world_boot_id": "boot-1",
    }
    with RunStorage(database) as storage:
        campaign_id = storage.create_campaign(
            name=spec.name,
            config_path=config_path.resolve(),
            character_profile_path=spec.character_profile,
            target_level=spec.target_level,
        )
        storage.record_campaign_checkpoint(
            campaign_id,
            segment_id=None,
            run_id=None,
            phase="ready",
            reason="ready",
            state=state,
        )

    route_error = (
        "loot liquidation route remained blocked by the source-backed "
        "Midgaard drunk after 3 bounded rechecks"
    )

    async def failed_segment(character, profile_path: Path) -> RunResult:
        with RunStorage(database) as storage:
            run_id = storage.create_run(
                scenario_name=f"sell-loot:{character.name}",
                scenario_path=profile_path,
            )
            storage.record_event(
                run_id,
                kind="state",
                payload={
                    "state": "failed",
                    "error": route_error,
                    "magic_shop_route_blocked_by_drunk": True,
                    "city_shop_route_wait_attempts": 3,
                    "campaign_sale_rejections": [],
                },
            )
            storage.finish_run(run_id, status="failed", error=route_error)
        raise RuntimeError(route_error)

    class LiquidationRunner(CampaignRunner):
        def _policy_for_state(self, current_state) -> ProgressionPolicy:
            return policy

    result = asyncio.run(
        LiquidationRunner(
            spec,
            config_path,
            segment_runner=failed_segment,
        ).run()
    )

    assert result.status == "ready"
    assert result.state["magic_shop_route_blocked_by_drunk"] is True
    assert result.state["city_shop_route_wait_attempts"] == 3
    assert result.state["campaign_city_shop_route_cooldown"] == 2
    with RunStorage(database) as storage:
        checkpoint = storage.get_latest_campaign_checkpoint(campaign_id)
        segment = storage.list_campaign_segments(campaign_id)[-1]
        campaign = storage.get_campaign(campaign_id)
    assert checkpoint is not None
    assert checkpoint["reason"] == "segment_route_hazard"
    assert json.loads(checkpoint["state_json"])[
        "magic_shop_route_blocked_by_drunk"
    ] is True
    assert segment["status"] == "ready"
    assert campaign is not None
    assert campaign["status"] == "ready"


def test_open_campaign_repairs_noop_liquidation_baseline(tmp_path) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    state = {
        "name": "Campaignmage",
        "level": 8,
        "xp": 20_000,
        "room_vnum": "3054",
        "area": "Midgaard",
        "inventory": [[{"short_desc": "hard leather boots"}]],
        "campaign_worn_equipment": [],
    }
    with RunStorage(database) as storage:
        campaign_id = storage.create_campaign(
            name=spec.name,
            config_path=config_path.resolve(),
            character_profile_path=spec.character_profile,
            target_level=spec.target_level,
        )
        run_id = storage.create_run(
            scenario_name="sell-loot:Campaignmage",
            scenario_path=spec.character_profile,
        )
        storage.finish_run(run_id, status="success")
        noop_start_state = {
            **state,
            "campaign_liquidation_baseline": [],
        }
        segment_id = storage.start_campaign_segment(
            campaign_id,
            phase="liquidate-loot",
            start_state=noop_start_state,
        )
        storage.finish_campaign_segment(
            segment_id,
            status="success",
            run_id=run_id,
            end_state=noop_start_state,
            command_count=0,
            duration_seconds=0,
        )
        storage.record_campaign_checkpoint(
            campaign_id,
            segment_id=segment_id,
            run_id=run_id,
            phase="restock-provisions",
            reason="segment_complete",
            state={
                **state,
                "campaign_liquidation_baseline": ["hard leather boots"],
            },
        )

        runner = CampaignRunner(spec, config_path)
        resumed_id, repaired = runner._open_campaign(storage)
        checkpoint = storage.get_latest_campaign_checkpoint(campaign_id)

    assert resumed_id == campaign_id
    assert "campaign_liquidation_baseline" not in repaired
    assert checkpoint is not None
    assert checkpoint["reason"] == _CAMPAIGN_METADATA_REPAIRED_REASON


