def test_campaign_selects_sack_phase_from_persisted_inventory(
    tmp_path,
    monkeypatch,
) -> None:
    config_path, _database = _write_campaign_files(tmp_path)
    runner = CampaignRunner(load_campaign_spec(config_path), config_path)

    before = runner._policy_for_state(
        {"level": 8, "inventory": [[{"short_desc": "a big pot pie"}]]}
    )
    after = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[
                {"short_desc": "a large sack"},
                {"short_desc": "a big pot pie"},
            ]],
        }
    )

    assert before.policy_id == "midennir-sack-8-10"
    assert after.policy_id == "ambush-war-dog-8-9"

    runner._historical_large_sack = True
    after_lodging = runner._policy_for_state(
        {"level": 8, "inventory": [[{"short_desc": "a big pot pie"}]]}
    )
    assert after_lodging.policy_id == "ambush-war-dog-8-9"
    with_loot = runner._policy_for_state(
        {"level": 8, "inventory": [[{"short_desc": "hard leather boots"}]]}
    )
    assert with_loot.policy_id == "liquidate-loot"
    after_own_corpse_recovery = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[
                {"short_desc": "hard leather boots"},
                {"short_desc": "a big pot pie"},
            ]],
            "acquired_items": [
                {
                    "item": (
                        "hard leather boots from the corpse of Campaignmage"
                    )
                }
            ],
        }
    )
    assert after_own_corpse_recovery.policy_id == "ambush-war-dog-8-9"

    with_useful_carried_collars = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[
                {"short_desc": "a war dog collar", "quan": "2"},
                {"short_desc": "a big pot pie"},
            ]],
            "stats": {"carry_wt": 102, "maxcarry_wt": 140},
        }
    )
    assert with_useful_carried_collars.policy_id == "ambush-war-dog-8-9"

    with_two_collars_under_temporary_capacity_pressure = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[
                {"short_desc": "a war dog collar", "quan": "2"},
                {"short_desc": "a big pot pie", "quan": "5"},
            ]],
            "stats": {"carry_wt": 126, "maxcarry_wt": 140},
        }
    )
    assert (
        with_two_collars_under_temporary_capacity_pressure.policy_id
        == "ambush-war-dog-8-9"
    )

    sack = ObjectSource(
        4529,
        "sack large",
        "a large sack",
        15,
        (400, 0, 0, 0),
        0,
        weight=50,
    )
    runner._gear_catalog = GearCatalog({sack.vnum: sack})
    with_oversized_sack_after_full_vault = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[
                {"short_desc": "a large sack"},
                {"short_desc": "a big pot pie"},
                {"short_desc": "a buffalo water skin"},
            ]],
            "stats": {"carry_wt": 135, "maxcarry_wt": 140},
            "campaign_has_weapon": True,
            "vault_storage_rejected": True,
        }
    )
    assert with_oversized_sack_after_full_vault.policy_id == "vault-spare-gear"

    with_collar_weight_pressure = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[{"short_desc": "a war dog collar", "quan": "3"}]],
            "stats": {"carry_wt": 126, "maxcarry_wt": 140},
        }
    )
    assert with_collar_weight_pressure.policy_id == "liquidate-loot"

    without_food = runner._policy_for_state(
        {
            "level": 8,
            "inventory": [[{"short_desc": "a buffalo water skin"}]],
            "stats": {"carry_wt": 102, "maxcarry_wt": 250},
        }
    )
    assert without_food.policy_id == "restock-provisions"

    urgent_food_with_full_loot = runner._policy_for_state(
        {
            "level": 8,
            "hunger": 0,
            "inventory": [[
                {"short_desc": "hard leather boots"},
                {"short_desc": "a buffalo water skin"},
            ]],
            "stats": {
                "carry_num": 36,
                "maxcarry_num": 36,
                "carry_wt": 250,
                "maxcarry_wt": 250,
            },
        }
    )
    assert urgent_food_with_full_loot.policy_id == "liquidate-loot"

    with_serialized_food = runner._policy_for_state(
        {
            "level": 8,
            "inventory": (
                '[[{"quan":"10","short_desc":"a big pot pie"},'
                '{"quan":"1","short_desc":"a buffalo water skin"}]]'
            ),
        }
    )
    assert with_serialized_food.policy_id == "ambush-war-dog-8-9"

    with_food_after_failed_funding = {
        "level": 8,
        "inventory": (
            '[[{"quan":"2","short_desc":"a big pot pie"},'
            '{"quan":"1","short_desc":"a buffalo water skin"}]]'
        ),
        _PROVISION_FUNDING_REQUIRED_KEY: True,
        _PROVISION_FUNDING_LAST_ATTEMPT_KEY: {
            "boot_id": "boot-1",
            "candidate_key": "test.are:123:456",
            "completed_kill": False,
        },
    }
    assert runner._policy_for_state(with_food_after_failed_funding).policy_id == (
        "ambush-war-dog-8-9"
    )

    with_food_after_failed_flight_funding = {
        **with_food_after_failed_funding,
        _PROVISION_FUNDING_REQUIRED_KEY: False,
        _FLIGHT_FUNDING_REQUIRED_KEY: True,
        "affects": [],
        "magic_shop_purchase_failed": True,
        "campaign_flight_loan_attempted": True,
    }
    selected_after_failed_flight = runner._policy_for_state(
        with_food_after_failed_flight_funding
    )
    assert selected_after_failed_flight.execution == "source-ranked-hunt"
    assert selected_after_failed_flight.policy_id.startswith(
        "source-ranked-hunt-"
    )


    with_food_during_flight_retry_cooldown = {
        **with_food_after_failed_flight_funding,
        "currencies": {"gold": 1},
        _FLIGHT_PURCHASE_COOLDOWN_KEY: 3,
    }
    assert runner._policy_for_state(
        with_food_during_flight_retry_cooldown
    ).policy_id == "ambush-war-dog-8-9"

    with_food_below_flight_price_during_retry_cooldown = {
        **with_food_after_failed_flight_funding,
        "currencies": {"silver": 9, "copper": 9},
        _MAGIC_SHOP_FLIGHT_PRICE_KEY: 147,
        _FLIGHT_PURCHASE_COOLDOWN_KEY: 3,
    }
    assert runner._policy_for_state(
        with_food_below_flight_price_during_retry_cooldown
    ).policy_id == "ambush-war-dog-8-9"

    flight_candidate = replace(
        _source_test_candidate(
            target="a flight target",
            level_range=(18, 22),
            mobile_vnum=700,
            room_vnum=800,
        ),
        requires_flight=True,
    )
    ground_candidate = _source_test_candidate(
        target="a ground target",
        level_range=(18, 22),
        mobile_vnum=701,
        room_vnum=801,
    )
    selection_calls: list[bool] = []

    def select_candidate(
        state,
        *,
        require_no_flight=False,
        **kwargs,
    ):
        selection_calls.append(require_no_flight)
        return ground_candidate if require_no_flight else flight_candidate

    monkeypatch.setattr(
        "dd4tester.campaign.policy_for",
        lambda *args, **kwargs: _SOURCE_RANKED_HUNT_POLICY,
    )
    monkeypatch.setattr(
        runner,
        "_select_source_ranked_candidate",
        select_candidate,
    )
    cooldown_policy = runner._policy_for_state(
        {
            "level": 20,
            "world_boot_id": "boot-1",
            "inventory": [[{"short_desc": "a big pot pie"}]],
            "affects": [],
            "campaign_flight_purchase_cooldown": 3,
        }
    )
    assert selection_calls == [False, True]
    assert cooldown_policy.execution == "source-ranked-hunt"
    assert cooldown_policy.requires_flight is False

    selection_calls.clear()

    def select_without_ground_target(
        state,
        *,
        require_no_flight=False,
        **kwargs,
    ):
        selection_calls.append(require_no_flight)
        return None if require_no_flight else flight_candidate

    monkeypatch.setattr(
        runner,
        "_select_source_ranked_candidate",
        select_without_ground_target,
    )
    funding_fallback = runner._policy_for_state(
        {
            "level": 20,
            "world_boot_id": "boot-1",
            "inventory": [[{"short_desc": "a big pot pie"}]],
            "affects": [],
            "campaign_flight_purchase_cooldown": 3,
            _FLIGHT_FUNDING_REQUIRED_KEY: True,
        }
    )
    assert selection_calls == [False, True]
    assert funding_fallback.policy_id == "provision-funding"

    selection_calls.clear()
    affordable_flight_fallback = runner._policy_for_state(
        {
            "level": 20,
            "world_boot_id": "boot-1",
            "inventory": [[{"short_desc": "a big pot pie"}]],
            "affects": [],
            "currencies": {"silver": 14, "copper": 20},
            _PROVISION_FUNDING_REQUIRED_KEY: True,
            _FLIGHT_FUNDING_REQUIRED_KEY: True,
            "magic_shop_purchase_failed": True,
            "campaign_flight_loan_attempted": True,
            "campaign_flight_purchase_cooldown": 3,
            "magic_shop_flight_price": 147,
        }
    )
    assert selection_calls == [False, True]
    assert affordable_flight_fallback.policy_id == "buy-flight-potion"

    selection_calls.clear()
    affordable_flight_after_cleared_failure = runner._policy_for_state(
        {
            "level": 20,
            "world_boot_id": "boot-1",
            "inventory": [[{"short_desc": "a big pot pie"}]],
            "affects": [],
            "currencies": {"silver": 14, "copper": 20},
            "magic_shop_purchase_failed": False,
            "campaign_flight_purchase_cooldown": 3,
            "magic_shop_flight_price": 147,
        }
    )
    assert selection_calls == [False, True]
    assert affordable_flight_after_cleared_failure.policy_id == (
        "buy-flight-potion"
    )

    affordable_flight_with_pending_requirement = runner._policy_for_state(
        {
            "level": 20,
            "world_boot_id": "boot-1",
            "inventory": [[{"short_desc": "a big pot pie"}]],
            "affects": [],
            "currencies": {"silver": 14, "copper": 20},
            _PROVISION_FUNDING_REQUIRED_KEY: True,
            _FLIGHT_FUNDING_REQUIRED_KEY: True,
            "magic_shop_purchase_failed": False,
            "campaign_flight_purchase_cooldown": 3,
            "magic_shop_flight_price": 147,
        }
    )
    assert affordable_flight_with_pending_requirement.policy_id == (
        "buy-flight-potion"
    )

    monkeypatch.setattr(
        "dd4tester.campaign._select_provision_funding_candidate",
        lambda *args, **kwargs: ground_candidate,
    )
    blocked_shop_funding_fallback = runner._policy_for_state(
        {
            "level": 20,
            "world_boot_id": "boot-1",
            "inventory": [[{"short_desc": "a big pot pie"}]],
            "affects": [],
            "currencies": {"silver": 14, "copper": 20},
            "magic_shop_purchase_failed": False,
            _MAGIC_SHOP_ROUTE_BLOCKED_KEY: True,
            "campaign_flight_purchase_cooldown": 3,
            "magic_shop_flight_price": 147,
        }
    )
    assert blocked_shop_funding_fallback.policy_id == "provision-funding"
    assert blocked_shop_funding_fallback.execution == "provision-funding"
    monkeypatch.undo()

    without_food_after_failed_funding = {
        **with_food_after_failed_flight_funding,
        "inventory": '[[{"quan":"1","short_desc":"a buffalo water skin"}]]',
        _PROVISION_FUNDING_REQUIRED_KEY: True,
    }
    assert runner._policy_for_state(without_food_after_failed_funding).policy_id == (
        "provision-funding"
    )



