def _record_segment_run(
    database: Path,
    profile_path: Path,
    final_state: dict[str, int],
    *,
    scenario_name: str = "starter:Campaignmage",
) -> RunResult:
    with RunStorage(database) as storage:
        run_id = storage.create_run(
            scenario_name=scenario_name,
            scenario_path=profile_path,
        )
        storage.record_event(run_id, kind="command", payload={"command": "look"})
        storage.finish_run(run_id, status="success")
    return RunResult(
        run_id=run_id,
        status="success",
        transcript_path=Path("transcripts/campaign.jsonl"),
        database_path=database,
        final_state=final_state,
    )


@pytest.mark.parametrize("quest_kind", ["object", "hoard"])
def test_quest_target_dispatch_preserves_exact_object_vnum(
    tmp_path,
    monkeypatch,
    quest_kind: str,
) -> None:
    config_path, database = _write_campaign_files(tmp_path)
    spec = load_campaign_spec(config_path)
    world = WorldSource(
        objects={
            9001: ObjectSource(
                9001,
                "token",
                "a quest token",
                12,
                (0,),
                1,
            )
        },
        rooms={
            3001: RoomSource(
                3001,
                "Recall",
                "test.are",
                exits={"north": ExitSource("north", 9000, 0, -1)},
            ),
            9000: RoomSource(
                9000,
                "Quest Room",
                "test.are",
                exits={"south": ExitSource("south", 3001, 0, -1)},
            ),
        },
    )
    captured: dict[str, object] = {}

    class FakeRunner:
        def __init__(self, character, profile_path, **kwargs):
            captured.update(kwargs)

        async def run(self):
            return _record_segment_run(
                database,
                spec.character_profile,
                {"level": 24},
            )

    monkeypatch.setattr("dd4tester.campaign.StarterBotRunner", FakeRunner)
    monkeypatch.setattr(
        "dd4tester.campaign.load_world_source",
        lambda *args, **kwargs: world,
    )
    policy = ProgressionPolicy(
        policy_id="quest-target-run-test",
        minimum_level=24,
        maximum_level=24,
        status="research",
        execution="quest-target-run",
        summary="Run one generated quest target.",
        evidence=(),
        practice_skill=None,
    )

    asyncio.run(
        _run_policy_segment(
            spec.character,
            spec.character_profile,
            policy,
            current_state={
                "level": 24,
                "quest_status": {
                    "active": 1,
                    "complete": 0,
                    "type": quest_kind,
                    "object_vnum": 9001,
                    "room_vnum": 9000,
                },
            },
            character_level=24,
        )
    )

    (stop,) = captured["fastwalk_hunt_stops"]
    assert stop.required_items == ("token",)
    assert stop.source_loot_object_vnums == (9001,)
    if quest_kind == "hoard":
        assert stop.actions.count("dig") == 12


